import {compare} from "bcryptjs";import {z} from "zod";import {db} from "@/lib/database";import {isRegularAgent} from "@/lib/regular-agent";import {ADMIN_SESSION_COOKIE,AGENT_SESSION_COOKIE,BPO_SESSION_COOKIE,createSession} from "@/lib/session";import {createDecipheriv,createHmac} from "node:crypto";
const schema=z.object({username:z.string().trim().toLowerCase(),password:z.string().min(1),portal:z.enum(["agent","admin","bpo"]).default("agent"),otp:z.string().optional()});
function totp(secret:string,code:string){const alphabet="ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";let bits="";for(const c of secret)bits+=alphabet.indexOf(c).toString(2).padStart(5,"0");const key=Buffer.alloc(Math.floor(bits.length/8));for(let i=0;i<key.length;i++)key[i]=parseInt(bits.slice(i*8,i*8+8),2);const now=Math.floor(Date.now()/30000);return[-1,0,1].some(x=>{const b=Buffer.alloc(8);b.writeBigUInt64BE(BigInt(now+x));const h=createHmac("sha1",key).update(b).digest(),o=h[h.length-1]&15;return String((h.readUInt32BE(o)&2147483647)%1000000).padStart(6,"0")===code})}
function unseal(v:string){const key=Buffer.from((process.env.AUTH_SECRET||"maxai-bpo-settings-secret").padEnd(32,"0").slice(0,32));const[a,b,c]=v.split(".");const d=createDecipheriv("aes-256-gcm",key,Buffer.from(a,"base64url"));d.setAuthTag(Buffer.from(b,"base64url"));return Buffer.concat([d.update(Buffer.from(c,"base64url")),d.final()]).toString()}
export async function POST(request:Request){try{const raw=await request.json();if(!["admin","bpo"].includes(raw.portal))return Response.json({message:"Please use the BPO or controller login."},{status:403});const p=schema.safeParse(raw);if(!p.success)return Response.json({message:"Username/email and password are required."},{status:400});const c=await db({ensureSchema:false}),q=await c.query("SELECT id,password_hash,status,role,email,email_verified,two_factor_enabled,two_factor_secret FROM agents WHERE username=$1 OR email=$1 LIMIT 1",[p.data.username]),a=q.rows[0];if(!a||!(await compare(p.data.password,a.password_hash)))return Response.json({message:"Invalid username/email or password."},{status:401});if(a.role!==p.data.portal.toUpperCase()&&!(p.data.portal==="agent"&&a.role==="AGENT"))return Response.json({message:"Invalid credentials."},{status:403});if(p.data.portal==="agent"&&a.role==="AGENT"&&!(await isRegularAgent(a.id)))return Response.json({message:"BPO calling agents can only be managed from the BPO workspace."},{status:403});if(p.data.portal==="bpo"&&!a.email_verified)return Response.json({message:"Please verify your email before logging in."},{status:403});if(a.status==="SUSPENDED")return Response.json({message:"Your account is blocked. Please check your email or contact support."},{status:403});if(a.status!=="APPROVED")return Response.json({message:"Your account is pending admin approval."},{status:403});if(p.data.portal==="bpo"&&a.two_factor_enabled){if(!p.data.otp)return Response.json({message:"Enter your authenticator OTP.",requiresTwoFactor:true},{status:401});if(!a.two_factor_secret||!totp(unseal(a.two_factor_secret),p.data.otp))return Response.json({message:"Incorrect authenticator OTP.",requiresTwoFactor:true},{status:401})}const cookie=p.data.portal==="admin"?ADMIN_SESSION_COOKIE:p.data.portal==="bpo"?BPO_SESSION_COOKIE:AGENT_SESSION_COOKIE;const response=Response.json({message:"Welcome back!",redirectTo:a.role==="BPO"?"/bpo":a.role==="ADMIN"?"/controler":"/agent"});response.headers.append("Set-Cookie",`${cookie}=${await createSession({agentId:a.id,role:a.role})}; Path=/; HttpOnly; SameSite=Lax; Max-Age=604800`);return response}catch(error){console.error("Login failed",error);return Response.json({message:"Unable to sign in right now."},{status:503})}}
